// Key state from channel 1: row 0 held, row 1 pressed this frame, row 2 toggled.
const int KEY_SPACE = 32;
const int KEY_LEFT = 37;
const int KEY_A = 65;

float held(int key) { return texelFetch(iChannel1, ivec2(key, 0), 0).x; }
float toggled(int key) { return texelFetch(iChannel1, ivec2(key, 2), 0).x; }
float pressed(int key)
{
    return texture(iChannel1, vec2((float(key) + 0.5) / 256.0, 1.5 / 3.0)).x;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord / iResolution.xy;
    vec3 calm = vec3(0.15, 0.35, 0.7);
    vec3 hot = vec3(1.0, 0.45, 0.1);
    vec3 col = mix(calm, hot, held(KEY_SPACE));
    col += 0.3 * toggled(KEY_A) + 0.3 * pressed(KEY_LEFT);
    col *= 0.6 + 0.4 * uv.y;
    fragColor = vec4(col, 1.0);
}
